window.__PAGE_RUNTIME_PARTIALS__["partials/guia-07-planificar-ciberseguridad-content.html"] = "\u003cbutton class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Menú\"\u003e\u0026#9776;\u003c/button\u003e\n\u003cbutton class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\"\u003e\u0026#9776;\u003c/button\u003e\n\n\u003cdiv class=\"layout app-layout\"\u003e\n  \u003cnav class=\"sidebar\" id=\"sidebar\"\u003e\n    \u003cdiv class=\"sidebar-logo\"\u003e\n      \u003cdiv class=\"badge\"\u003eSENA \u0026middot; FPI\u003c/div\u003e\n      \u003ch2\u003eGu\u0026iacute;a 7 - Planificar la informaci\u0026oacute;n seg\u0026uacute;n criterios de ciberseguridad\u003c/h2\u003e\n      \u003cp\u003eSistemas Teleinform\u0026aacute;ticos\u003c/p\u003e\n      \u003cbutton class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\"\u003e\u0026#9664;\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"sidebar-ficha\" id=\"sb-ficha-ok\" style=\"display:none\"\u003e\n      \u003cdiv class=\"sf-label\"\u003eTu grupo\u003c/div\u003e\n      \u003cdiv class=\"sf-inst\" id=\"sb-inst\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-meta\" id=\"sb-grupo-meta\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-badge\" id=\"sb-badge\"\u003e\u003c/div\u003e\n    \u003c/div\u003e\n    \u003cdiv class=\"sidebar-noficha\" id=\"sb-ficha-warn\"\u003e\n      \u003ca href=\"index.html\"\u003eInicio | Seleccionar grupo / ficha\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"progress-wrap\"\u003e\n      \u003cdiv class=\"progress-label\"\u003e\n        \u003cspan\u003eProgreso\u003c/span\u003e\n        \u003cspan id=\"progressValue\"\u003e0%\u003c/span\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"progress-bar-bg\"\u003e\n        \u003cdiv class=\"progress-bar\" id=\"progressBar\"\u003e\u003c/div\u003e\n      \u003c/div\u003e\n      \u003cp class=\"progress-note\"\u003eEl avance se guarda localmente en este navegador.\u003c/p\u003e\n      \u003cbutton type=\"button\" class=\"reset-button\" id=\"resetProgress\"\u003eReiniciar respuestas\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eInformaci\u0026oacute;n\u003c/div\u003e\n      \u003ca class=\"nav-link active\" href=\"#identificacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128203;\u003c/span\u003e Identificaci\u0026oacute;n\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#presentacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128075;\u003c/span\u003e Presentaci\u0026oacute;n\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eActividades\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#reflexion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128172;\u003c/span\u003e 3.1 Reflexi\u0026oacute;n Inicial\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#contexto\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128269;\u003c/span\u003e 3.2 Contextualizaci\u0026oacute;n\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#apropiacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128218;\u003c/span\u003e 3.3 Apropiaci\u0026oacute;n\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#transferencia\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128640;\u003c/span\u003e 3.4 Transferencia\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eRecursos\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#evidencias\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128202;\u003c/span\u003e Evidencias\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128214;\u003c/span\u003e Glosario\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#referencias\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128279;\u003c/span\u003e Referencias\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eGu\u0026iacute;a asignada\u003c/div\u003e\n      \u003ca class=\"nav-guide current\" id=\"currentGuideNavLink\" href=\"grupo-11a-guia-07-planificar-informacion-ciberseguridad.html\" data-current-file=\"grupo-11a-guia-07-planificar-informacion-ciberseguridad.html\"\u003e\n        \u003cspan class=\"g-icon\"\u003e\u0026#128215;\u003c/span\u003e\n        \u003cspan class=\"g-info\"\u003e\n          \u003cspan class=\"g-num\"\u003eGu\u0026iacute;a 7\u003c/span\u003e\n          \u003cspan class=\"g-name\" id=\"currentGuideNavLabel\"\u003ePlanificar la informaci\u0026oacute;n seg\u0026uacute;n criterios de ciberseguridad | 11A\u003c/span\u003e\n        \u003c/span\u003e\n        \u003cspan class=\"g-tag actual\"\u003eActual\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003ca class=\"nav-home-link\" href=\"calendario-academico-2026.html\"\u003e\u0026#128197; \u003cspan\u003eCalendario 2026\u003c/span\u003e\u003c/a\u003e\n    \u003ca class=\"nav-home-link\" href=\"index.html\"\u003e\u0026#127968; \u003cspan\u003eVolver al Inicio\u003c/span\u003e\u003c/a\u003e\n  \u003c/nav\u003e\n\n  \u003cdiv class=\"main app-main\"\u003e\n    \u003cdiv class=\"topbar\"\u003e\n      \u003cdiv class=\"topbar-title\"\u003e\n        \u003cstrong\u003eGu\u0026iacute;a 7 - Planificar la informaci\u0026oacute;n seg\u0026uacute;n criterios de ciberseguridad\u003c/strong\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"topbar-meta\"\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#9201;\u003c/span\u003e\u003cspan\u003e40 horas\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#128197;\u003c/span\u003e\u003cspan\u003e2026\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#127979;\u003c/span\u003e\u003cspan id=\"topbarCampus\"\u003eSanta B\u0026aacute;rbara | 11A\u003c/span\u003e\u003c/span\u003e\n      \u003c/div\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"content\"\u003e\n      \u003cdiv class=\"hero\" id=\"inicio\"\u003e\n        \u003cdiv class=\"tag\"\u003eGu\u0026iacute;a 7 | Fase: Planeaci\u0026oacute;n\u003c/div\u003e\n        \u003ch1\u003ePlanificar la informaci\u0026oacute;n seg\u0026uacute;n criterios de ciberseguridad\u003c/h1\u003e\n        \u003cp\u003e\n          En esta gu\u0026iacute;a aprender\u0026aacute;s a planificar la seguridad de la informaci\u0026oacute;n aplicando\n          criterios t\u0026eacute;cnicos y normativos (Triada CIA, ISO 27001, NIST CSF, Ley 1273 de 2009)\n          para diagnosticar vulnerabilidades, aplicar controles de \u003cem\u003ehardening\u003c/em\u003e y elaborar un\n          Plan de Ciberseguridad real para una MiPyme del Magdalena Medio y el Occidente de Boyac\u0026aacute;.\n        \u003c/p\u003e\n        \u003cdiv class=\"hero-meta\"\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127963; SENA \u0026mdash; Servicio Nacional de Aprendizaje\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#128205; Competencia: Operar herramientas inform\u0026aacute;ticas y digitales\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#9201; 40 horas\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127891; C\u0026oacute;digo: 233108 \u0026middot; V1\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"identificacion\" class=\"section-title\"\u003eIdentificaci\u0026oacute;n de la Gu\u0026iacute;a\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f5e9\"\u003e\u0026#128203;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eDatos del Programa de Formaci\u0026oacute;n\u003c/h3\u003e\n              \u003cp\u003eInformaci\u0026oacute;n oficial del programa y la competencia\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table ident-table\"\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eDenominaci\u0026oacute;n del Programa\u003c/td\u003e\u003ctd\u003eT\u0026eacute;cnico en Sistemas Teleinform\u0026aacute;ticos\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eC\u0026oacute;digo del Programa\u003c/td\u003e\u003ctd\u003e233108 \u0026middot; V1\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eNombre del Proyecto Formativo\u003c/td\u003e\u003ctd\u003eFortalecimiento de los servicios Teleinform\u0026aacute;ticos de equipos y redes en las MiPymes de la regi\u0026oacute;n de Boyac\u0026aacute;.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eFase del Proyecto\u003c/td\u003e\u003ctd\u003ePlaneaci\u0026oacute;n\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eActividad del Proyecto\u003c/td\u003e\u003ctd\u003ePlanificar los procesos de seguridad de la informaci\u0026oacute;n y gesti\u0026oacute;n de riesgos para los Sistemas Teleinform\u0026aacute;ticos de las MiPymes.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCompetencia\u003c/td\u003e\u003ctd\u003e220501121 - Operar herramientas inform\u0026aacute;ticas y digitales de acuerdo con protocolos y manuales t\u0026eacute;cnicos.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eResultado de Aprendizaje\u003c/td\u003e\u003ctd\u003eRAP 03 - Planificar la informaci\u0026oacute;n seg\u0026uacute;n criterios de ciberseguridad.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eDuraci\u0026oacute;n\u003c/td\u003e\u003ctd\u003e40 horas\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"presentacion\" class=\"section-title\"\u003ePresentaci\u0026oacute;n\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e3f2fd\"\u003e\u0026#128075;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eBienvenida a la Gu\u0026iacute;a\u003c/h3\u003e\n              \u003cp\u003eConoce el contexto, el alcance y las metas de este recorrido formativo\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\"\u003e\n            \u0026iexcl;Bienvenido, aprendiz! Las ferreter\u0026iacute;as, droguer\u0026iacute;as, cooperativas agropecuarias y\n            oficinas del Magdalena Medio y el Occidente de Boyac\u0026aacute; dependen cada vez m\u0026aacute;s de la\n            tecnolog\u0026iacute;a para funcionar, pero la mayor\u0026iacute;a no cuenta con ning\u0026uacute;n control de\n            seguridad sobre su informaci\u0026oacute;n. Un solo clic en un correo falso puede cifrar todos los\n            archivos de una empresa y dejarla sin operar.\n          \u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003e\n            Ah\u0026iacute; radica la importancia de esta gu\u0026iacute;a: aprender\u0026aacute;s a planificar la seguridad de la\n            informaci\u0026oacute;n aplicando criterios t\u0026eacute;cnicos y normativos \u0026mdash; Triada CIA, ISO 27001,\n            NIST CSF, Ley 1273 de 2009 \u0026mdash; para diagnosticar vulnerabilidades, aplicar controles de\n            \u003cem\u003ehardening\u003c/em\u003e y elaborar un plan de ciberseguridad real para una MiPyme de tu regi\u0026oacute;n.\n            Esta competencia es directamente aplicable en tu vida laboral: el t\u0026eacute;cnico que sabe\n            proteger la informaci\u0026oacute;n de una empresa tiene una ventaja real sobre quien solo sabe\n            instalar software.\n          \u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003e\n            En esta gu\u0026iacute;a seguir\u0026aacute;s un camino claro: comenzar\u0026aacute;s reflexionando sobre un caso real de\n            ataque inform\u0026aacute;tico para activar lo que ya sabes; luego estudiar\u0026aacute;s los conceptos\n            fundamentales de ciberseguridad y construir\u0026aacute;s un mapa conceptual; en la etapa pr\u0026aacute;ctica\n            analizar\u0026aacute;s el estado de seguridad de un equipo real con herramientas profesionales y\n            aplicar\u0026aacute;s controles de protecci\u0026oacute;n documentando cada cambio; y finalmente elaborar\u0026aacute;s un\n            Plan de Ciberseguridad para una MiPyme del Magdalena Medio.\n          \u003c/p\u003e\n          \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128204; Lo que necesitas para esta gu\u0026iacute;a\u003c/div\u003e\n            \u003cp\u003e\n              Equipo con Windows 10/11 (o m\u0026aacute;quina virtual), conexi\u0026oacute;n a internet y las\n              herramientas indicadas (la mayor\u0026iacute;a son gratuitas). Guarda tus evidencias con\n              nombres descriptivos. \u003cstrong\u003eLas capturas de pantalla son tu respaldo: sin\n              evidencia, no hay evaluaci\u0026oacute;n.\u003c/strong\u003e\n            \u003c/p\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.1 REFLEXIÓN INICIAL ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"reflexion\" class=\"section-title\"\u003e3.1 \u0026middot; Actividades de Reflexi\u0026oacute;n Inicial\u003c/div\u003e\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\n        \u003cp\u003eActivar lo que ya sabes sobre ciberseguridad, identificar dudas y preparar el terreno\n        conceptual para el estudio de los temas t\u0026eacute;cnicos. Todo el tiempo de reflexi\u0026oacute;n es trabajo\n        directo con el instructor.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-reflexion\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128172;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Reflexi\u0026oacute;n Inicial\u003c/h3\u003e\n              \u003cp\u003e2 actividades \u0026middot; Duraci\u0026oacute;n: 4 horas directas\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003c!-- ───────── Actividad 3.1.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eAn\u0026aacute;lisis del caso ElectroBoyc\u0026aacute; S.A.S.\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n de arranque\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e reflexionar individualmente sobre un caso real de ataque inform\u0026aacute;tico en una MiPyme de Puerto Boyac\u0026aacute;.\u003c/p\u003e\n\n              \u003carticle class=\"support-card\"\u003e\n                \u003ch3\u003eDatos de la actividad\u003c/h3\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003e\u0026#9201; Duraci\u0026oacute;n: 2 horas \u0026mdash; trabajo directo con el instructor.\u003c/li\u003e\n                  \u003cli\u003e\u0026#127979; Ambiente: laboratorio de inform\u0026aacute;tica o aula con videobeam.\u003c/li\u003e\n                  \u003cli\u003e\u0026#127919; Estrategia: Aprendizaje Basado en Problemas (ABP).\u003c/li\u003e\n                  \u003cli\u003e\u0026#128190; Herramientas TIC: LibreOffice Writer o Bloc de notas; Mentimeter (mentimeter.com) al cierre.\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"story-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003e\u0026#128187; Caso \u0026mdash; ElectroBoyc\u0026aacute; S.A.S., Puerto Boyac\u0026aacute; (Magdalena Medio)\u003c/h3\u003e\n                \u003cp\u003eEsta distribuidora de materiales el\u0026eacute;ctricos recibi\u0026oacute; un correo que parec\u0026iacute;a ser de su\n                banco, solicitando actualizar sus datos de acceso. Un empleado ingres\u0026oacute; su usuario y\n                contrase\u0026ntilde;a en el enlace del correo.\u003c/p\u003e\n                \u003cp\u003eAl d\u0026iacute;a siguiente, todos los archivos de la empresa aparecieron cifrados con el\n                mensaje: \u003cem\u003e\u0026laquo;Pague $3.000.000 en criptomonedas para recuperar sus datos.\u0026raquo;\u003c/em\u003e\u003c/p\u003e\n                \u003cp\u003eLa empresa no ten\u0026iacute;a copias de seguridad, el antivirus estaba desactivado y no\n                exist\u0026iacute;a ninguna pol\u0026iacute;tica de seguridad escrita.\u003c/p\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px;\"\u003e\n                \u003ch3\u003eBit\u0026aacute;cora individual de an\u0026aacute;lisis\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. \u0026iquest;Has escuchado antes sobre ataques como este? \u0026iquest;Qu\u0026eacute; sabes sobre c\u0026oacute;mo ocurren?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g7_311_pregunta1\" data-track placeholder=\"Escribe lo que recuerdes de noticias, conversaciones o experiencias previas.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. \u0026iquest;Por qu\u0026eacute; crees que una empresa peque\u0026ntilde;a como ElectroBoyc\u0026aacute; puede ser v\u0026iacute;ctima de un ciberataque?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g7_311_pregunta2\" data-track placeholder=\"Reflexiona sobre las debilidades t\u0026iacute;picas de una MiPyme.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Si fueras el t\u0026eacute;cnico de sistemas de ElectroBoyc\u0026aacute;, \u0026iquest;qu\u0026eacute; habr\u0026iacute;as recomendado ANTES del ataque? Lista al menos 3 medidas concretas.\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g7_311_pregunta3\" data-track placeholder=\"Numera 3 medidas t\u0026eacute;cnicas claras (ejemplo: copias de seguridad, antivirus, capacitaci\u0026oacute;n, etc.).\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. \u0026iquest;Qu\u0026eacute; informaci\u0026oacute;n de una empresa consideras m\u0026aacute;s valiosa? \u0026iquest;Por qu\u0026eacute; debe protegerse?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g7_311_pregunta4\" data-track placeholder=\"Piensa en datos de clientes, facturaci\u0026oacute;n, n\u0026oacute;mina, inventario, etc.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"caso311DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarCaso311\" class=\"btn-save-response\" onclick=\"actStd_save_caso311()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_caso311()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusCaso311\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#128483; Cierre con Mentimeter\u003c/div\u003e\n                \u003cp\u003eCuando el instructor abra Mentimeter (mentimeter.com) en pantalla, ingresa el c\u0026oacute;digo y agrega en la nube de palabras el t\u0026eacute;rmino que m\u0026aacute;s asocias con ciberseguridad.\u003c/p\u003e\n              \u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.1.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eSocializaci\u0026oacute;n en plenaria\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n de arranque\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e compartir en equipo las conclusiones del caso y construir colectivamente los saberes previos.\u003c/p\u003e\n\n              \u003carticle class=\"support-card\"\u003e\n                \u003ch3\u003eDatos de la actividad\u003c/h3\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003e\u0026#9201; Duraci\u0026oacute;n: 2 horas \u0026mdash; trabajo directo con el instructor.\u003c/li\u003e\n                  \u003cli\u003e\u0026#127979; Ambiente: laboratorio de inform\u0026aacute;tica o aula.\u003c/li\u003e\n                  \u003cli\u003e\u0026#128101; Estrategia: trabajo colaborativo en grupos de 3.\u003c/li\u003e\n                  \u003cli\u003e\u0026#128190; Herramientas TIC: Padlet (padlet.com) opcional para muro colaborativo.\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eEn grupos de tres, comparten sus respuestas de la actividad 3.1.1 durante 10 minutos.\u003c/li\u003e\n                  \u003cli\u003eCada grupo presenta al grupo general en m\u0026aacute;ximo 3 minutos: \u0026iquest;cu\u0026aacute;l fue el hallazgo m\u0026aacute;s importante?\u003c/li\u003e\n                  \u003cli\u003eEl instructor registra en el tablero las ideas clave que surgen.\u003c/li\u003e\n                  \u003cli\u003eSi el grupo usa Padlet, agrega una tarjeta con la medida de seguridad m\u0026aacute;s urgente para ElectroBoyc\u0026aacute;.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px;\"\u003e\n                \u003ch3\u003eAnotaci\u0026oacute;n en bit\u0026aacute;cora (m\u0026iacute;nimo 5 l\u0026iacute;neas)\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e\u0026iquest;Qu\u0026eacute; cambi\u0026oacute; en tu comprensi\u0026oacute;n del caso despu\u0026eacute;s de escuchar al grupo? \u0026iquest;Qu\u0026eacute; preguntas tienes para resolver durante la gu\u0026iacute;a?\u003c/span\u003e\n                  \u003ctextarea rows=\"6\" data-store=\"g7_312_bitacora\" data-track placeholder=\"Escribe los aprendizajes de la plenaria, los puntos en com\u0026uacute;n con tu equipo y las preguntas pendientes.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"plenaria312DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarPlenaria312\" class=\"btn-save-response\" onclick=\"actStd_save_plenaria312()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_plenaria312()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusPlenaria312\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.2 CONTEXTUALIZACIÓN ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"contexto\" class=\"section-title\"\u003e3.2 \u0026middot; Contextualizaci\u0026oacute;n e Identificaci\u0026oacute;n de Conocimientos\u003c/div\u003e\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\n        \u003cp\u003eConstruir la base conceptual para planificar la seguridad de la informaci\u0026oacute;n. El estudio\n        tem\u0026aacute;tico requiere 2 horas de trabajo independiente previas a la clase.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-contexto\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128269;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Contextualizaci\u0026oacute;n\u003c/h3\u003e\n              \u003cp\u003e2 actividades \u0026middot; Duraci\u0026oacute;n: 10 horas (8 directas + 2 independientes)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003c!-- ───────── Actividad 3.2.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eEstudio de contenidos de ciberseguridad (Bloques A y B)\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n diagn\u0026oacute;stica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e estudiar en equipo los 9 temas conceptuales y consolidar una tabla resumen exportada a PDF: \u003ccode\u003eBloqueAB_[TuNombre]_v1.0.pdf\u003c/code\u003e.\u003c/p\u003e\n\n              \u003carticle class=\"support-card\"\u003e\n                \u003ch3\u003eDatos de la actividad\u003c/h3\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003e\u0026#9201; Duraci\u0026oacute;n: 8 horas (6 directas + 2 independientes previas).\u003c/li\u003e\n                  \u003cli\u003e\u0026#127979; Ambiente: laboratorio con acceso a internet.\u003c/li\u003e\n                  \u003cli\u003e\u0026#127919; Estrategia: aula invertida + trabajo colaborativo.\u003c/li\u003e\n                  \u003cli\u003e\u0026#128190; Herramientas TIC: Cisco Skills for All (skillsforall.com), Google Sheets / LibreOffice Calc, Drive / OneDrive.\u003c/li\u003e\n                  \u003cli\u003e\u0026#128218; Material de apoyo: INCIBE (incibe.es/empresas/guias), NIST CSF 2.0, Ley 1273 de 2009.\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (2 horas, ANTES de la sesi\u0026oacute;n)\u003c/div\u003e\n                \u003cp\u003eEstudia los temas del Bloque A usando Cisco Skills for All e INCIBE. Toma apuntes en tu bit\u0026aacute;cora. Llega a clase con la triada CIA, los tipos de ataques y el \u003cem\u003ehardening\u003c/em\u003e de Windows revisados.\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:16px\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth style=\"width:30%\"\u003eTema (Bloque A)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eFundamentos de ciberseguridad\u003c/td\u003e\u003ctd\u003eAmenaza, vulnerabilidad, riesgo, activo de informaci\u0026oacute;n, incidente. Triada CIA. Diferencia entre seguridad inform\u0026aacute;tica y ciberseguridad.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eTipos de ciberataques\u003c/td\u003e\u003ctd\u003eMalware (virus, troyanos, ransomware, spyware), phishing, MITM, DoS, ingenier\u0026iacute;a social. Casos reales en Colombia.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eNormativa aplicable\u003c/td\u003e\u003ctd\u003eISO/IEC 27001 (SGSI), Ley 1273 de 2009, CONPES 3995, lineamientos MinTIC para MiPymes.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eControles de seguridad\u003c/td\u003e\u003ctd\u003ePreventivos, detectivos y correctivos. NIST CSF 2.0: Identificar, Proteger, Detectar, Responder, Recuperar.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eHardening de Windows\u003c/td\u003e\u003ctd\u003eDefender, Firewall (3 perfiles), SmartScreen, pol\u0026iacute;ticas de contrase\u0026ntilde;as, actualizaciones, BitLocker.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eCopias de seguridad\u003c/td\u003e\u003ctd\u003eCompleta, incremental, diferencial. Estrategia 3-2-1. Historial de archivos Windows, EaseUS Todo Backup Free.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:12px\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth style=\"width:30%\"\u003eTema (Bloque B)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eTipos de documentos de seguridad\u003c/td\u003e\u003ctd\u003ePol\u0026iacute;tica de seguridad, plan de ciberseguridad, inventario de activos con valoraci\u0026oacute;n de riesgo.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eInventario de activos\u003c/td\u003e\u003ctd\u003eClasificaci\u0026oacute;n hardware/software/datos/personas. Criticidad (Alto/Medio/Bajo). ID, nombre, tipo, propietario, amenaza y control.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eProtocolos b\u0026aacute;sicos\u003c/td\u003e\u003ctd\u003eAcceso a informaci\u0026oacute;n sensible, eliminaci\u0026oacute;n segura, respuesta ante incidentes.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones para la sesi\u0026oacute;n directa\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eEquipo de 3 personas. Distribuyan los 9 temas (m\u0026iacute;nimo 3 por integrante).\u003c/li\u003e\n                  \u003cli\u003e1.\u0026ordf; hora de clase: cada integrante explica brevemente sus temas (5 min/tema). Mientras escuchas, completa los apuntes.\u003c/li\u003e\n                  \u003cli\u003eAbran Google Sheets / LibreOffice Calc y creen una tabla con 3 columnas: \u0026laquo;Concepto / Control\u0026raquo;, \u0026laquo;\u0026iquest;En qu\u0026eacute; consiste?\u0026raquo;, \u0026laquo;Ejemplo en una MiPyme de Boyac\u0026aacute;\u0026raquo;. Una fila por tema.\u003c/li\u003e\n                  \u003cli\u003ePlenaria de cierre: cada equipo comparte su fila m\u0026aacute;s importante. Ajusta tu tabla con los aportes.\u003c/li\u003e\n                  \u003cli\u003eExporta a PDF: \u003ccode\u003eArchivo \u0026gt; Exportar como PDF\u003c/code\u003e (Calc) o \u003ccode\u003eArchivo \u0026gt; Descargar \u0026gt; PDF\u003c/code\u003e (Sheets). Nombre: \u003cstrong\u003eBloqueAB_[TuNombre]_v1.0.pdf\u003c/strong\u003e.\u003c/li\u003e\n                  \u003cli\u003eComparte el PDF con el instructor por el medio que \u0026eacute;l indique. Anota dudas en tu bit\u0026aacute;cora.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eRegistro del aprendiz\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Temas que estudiaste t\u0026uacute; (de los 9 distribuidos en tu equipo)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g7_321_temas\" data-track placeholder=\"Lista los 3 temas que te tocaron.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Tu fila m\u0026aacute;s importante de la tabla resumen (concepto, en qu\u0026eacute; consiste, ejemplo MiPyme)\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g7_321_fila\" data-track placeholder=\"Describe la fila que sustentaste en plenaria.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Dudas que quedaron para resolver antes del mapa conceptual\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g7_321_dudas\" data-track placeholder=\"Anota tus preguntas conceptuales pendientes.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"bloqueAB321DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarBloqueAB321\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueAB321()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_bloqueAB321()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusBloqueAB321\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.2.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eMapa conceptual de ciberseguridad RAP 03\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n diagn\u0026oacute;stica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e construir en equipo un mapa conceptual que integre los conceptos de ciberseguridad estudiados. Entregable: \u003ccode\u003eMapaConceptual_RAP03_[Equipo]_v1.0.pdf\u003c/code\u003e.\u003c/p\u003e\n\n              \u003carticle class=\"support-card\"\u003e\n                \u003ch3\u003eDatos de la actividad\u003c/h3\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003e\u0026#9201; Duraci\u0026oacute;n: 2 horas directas.\u003c/li\u003e\n                  \u003cli\u003e\u0026#127979; Ambiente: laboratorio con acceso a internet.\u003c/li\u003e\n                  \u003cli\u003e\u0026#127919; Estrategia: pensamiento visual colaborativo.\u003c/li\u003e\n                  \u003cli\u003e\u0026#128190; Herramientas TIC: CmapTools (cmap.ihmc.us), Canva (canva.com), MindMeister (mindmeister.com).\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/article\u003e\n\n              \u003cdiv style=\"background:#1b5e20;color:#fff;border-radius:8px 8px 0 0;padding:10px 16px;font-size:0.82rem;font-weight:700;letter-spacing:0.04em;display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:16px;margin-bottom:0\"\u003e\n                \u003cspan\u003e\u0026#128203; EVIDENCIA \u0026mdash; Tipo: Evidencia de Conocimiento\u003c/span\u003e\n                \u003cspan style=\"opacity:0.5\"\u003e|\u003c/span\u003e\n                \u003cspan\u003eInstrumento: Lista de Chequeo IE-01\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:0;border-radius:0 0 8px 8px;overflow:hidden;border:1px solid #c8e6c9;border-top:none\"\u003e\n                \u003ctable class=\"data-table\" style=\"margin:0\"\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd style=\"width:2.5rem;text-align:center;font-weight:700;background:#e8f5e9\"\u003eA\u003c/td\u003e\u003ctd\u003eM\u0026iacute;nimo \u003cstrong\u003e15 conceptos\u003c/strong\u003e conectados con palabras de enlace descriptivas (no solo l\u0026iacute;neas).\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"width:2.5rem;text-align:center;font-weight:700;background:#e8f5e9\"\u003eB\u003c/td\u003e\u003ctd\u003eLa relaci\u0026oacute;n l\u0026oacute;gica: tipos de ataques \u0026rarr; controles de seguridad \u0026rarr; inventario de activos \u0026rarr; plan de ciberseguridad.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"width:2.5rem;text-align:center;font-weight:700;background:#e8f5e9\"\u003eC\u003c/td\u003e\u003ctd\u003eLos 3 principios de la \u003cstrong\u003eTriada CIA\u003c/strong\u003e con su aplicaci\u0026oacute;n concreta en una MiPyme.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"width:2.5rem;text-align:center;font-weight:700;background:#e8f5e9\"\u003eD\u003c/td\u003e\u003ctd\u003eAl menos una normativa (ISO 27001, NIST CSF o Ley 1273) con su funci\u0026oacute;n.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"width:2.5rem;text-align:center;font-weight:700;background:#e8f5e9\"\u003eE\u003c/td\u003e\u003ctd\u003eAl menos 2 controles de \u003cem\u003ehardening\u003c/em\u003e de Windows nombrados con su funci\u0026oacute;n.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eCon tu equipo, elijan la herramienta: CmapTools (gratuito sin internet, cmap.ihmc.us), Canva \u0026gt; \u0026laquo;mapa conceptual\u0026raquo;, o MindMeister. Sin internet, papel y marcadores.\u003c/li\u003e\n                  \u003cli\u003eAntes de dise\u0026ntilde;ar en digital, hagan a mano un borrador de 10 minutos: concepto central, ramas principales, jerarqu\u0026iacute;a. El instructor revisa el borrador.\u003c/li\u003e\n                  \u003cli\u003eConstruyan el mapa incluyendo los 5 elementos A-E. Usen palabras de enlace claras: \u0026laquo;genera\u0026raquo;, \u0026laquo;se mitiga con\u0026raquo;, \u0026laquo;requiere\u0026raquo;, \u0026laquo;se documenta en\u0026raquo;, \u0026laquo;protege contra\u0026raquo;.\u003c/li\u003e\n                  \u003cli\u003eRevisen claridad: colores distintos por categor\u0026iacute;a, texto m\u0026iacute;nimo 12pt, jerarqu\u0026iacute;a visible.\u003c/li\u003e\n                  \u003cli\u003eExporten a PDF (CmapTools, Canva o MindMeister). Nombre: \u003cstrong\u003eMapaConceptual_RAP03_[Equipo]_v1.0.pdf\u003c/strong\u003e.\u003c/li\u003e\n                  \u003cli\u003ePresenten oralmente en 5 minutos por equipo. El instructor da retroalimentaci\u0026oacute;n con la Lista de Chequeo IE-01.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eRegistro del aprendiz\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Concepto central elegido por el equipo\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g7_322_central\" data-track placeholder=\"Ej.: Ciberseguridad para una MiPyme.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Ramas principales del mapa (m\u0026iacute;nimo 4)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g7_322_ramas\" data-track placeholder=\"Lista las ramas: ataques, controles, normativa, inventario...\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Palabras de enlace m\u0026aacute;s usadas\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g7_322_enlaces\" data-track placeholder=\"Ej.: \u0026laquo;se mitiga con\u0026raquo;, \u0026laquo;requiere\u0026raquo;, \u0026laquo;protege\u0026raquo;...\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Aplicaci\u0026oacute;n concreta de la Triada CIA en una MiPyme de Boyac\u0026aacute;\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g7_322_cia_mipyme\" data-track placeholder=\"Confidencialidad, Integridad, Disponibilidad: un ejemplo de cada uno.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"mapa322DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarMapa322\" class=\"btn-save-response\" onclick=\"actStd_save_mapa322()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_mapa322()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusMapa322\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-mapa322\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.3 APROPIACIÓN ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"apropiacion\" class=\"section-title\"\u003e3.3 \u0026middot; Actividades de Apropiaci\u0026oacute;n\u003c/div\u003e\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\n        \u003cp\u003eAplicar los conocimientos adquiridos en un equipo de c\u0026oacute;mputo real. Usar\u0026aacute;s herramientas\n        profesionales para diagnosticar y fortalecer la seguridad, documentando cada hallazgo y cada\n        acci\u0026oacute;n con capturas de pantalla.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-apropiacion\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128218;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Apropiaci\u0026oacute;n\u003c/h3\u003e\n              \u003cp\u003e2 actividades \u0026middot; Duraci\u0026oacute;n: 20 horas (16 directas + 4 independientes)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003c!-- ───────── Actividad 3.3.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eDiagn\u0026oacute;stico del estado de seguridad del equipo\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n t\u0026eacute;cnica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e diagnosticar el estado de seguridad de un equipo Windows real usando herramientas profesionales. Evidencia de Conocimiento y Desempe\u0026ntilde;o (IE-02 \u0026iacute;tems 1-6).\u003c/p\u003e\n\n              \u003carticle class=\"support-card\"\u003e\n                \u003ch3\u003eDatos de la actividad\u003c/h3\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003e\u0026#9201; Duraci\u0026oacute;n: 10 horas (8 directas + 2 independientes).\u003c/li\u003e\n                  \u003cli\u003e\u0026#127979; Ambiente: laboratorio con equipo Windows 10/11 asignado (o m\u0026aacute;quina virtual).\u003c/li\u003e\n                  \u003cli\u003e\u0026#127919; Estrategia: laboratorio pr\u0026aacute;ctico guiado \u0026mdash; Learning by Doing.\u003c/li\u003e\n                  \u003cli\u003e\u0026#128190; Herramientas TIC: Windows Security Center, Belarc Advisor (belarc.com), \u003ccode\u003esecpol.msc\u003c/code\u003e, \u003ccode\u003elusrmgr.msc\u003c/code\u003e, Recortes de Windows (\u003ckbd\u003eWin + May\u0026uacute;s + S\u003c/kbd\u003e) o Greenshot.\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/article\u003e\n\n              \u003cdiv style=\"background:#1b5e20;color:#fff;border-radius:8px 8px 0 0;padding:10px 16px;font-size:0.82rem;font-weight:700;letter-spacing:0.04em;display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:16px;margin-bottom:0\"\u003e\n                \u003cspan\u003e\u0026#128203; EVIDENCIA \u0026mdash; Tipo: Conocimiento + Desempe\u0026ntilde;o\u003c/span\u003e\n                \u003cspan style=\"opacity:0.5\"\u003e|\u003c/span\u003e\n                \u003cspan\u003eInstrumento: Lista de Chequeo IE-02 (\u0026iacute;tems 1-6)\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:0;border-radius:0 0 8px 8px;overflow:hidden;border:1px solid #c8e6c9;border-top:none\"\u003e\n                \u003ctable class=\"data-table\" style=\"margin:0\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; diagnosticar?\u003c/th\u003e\n                      \u003cth\u003eHerramienta / Ruta\u003c/th\u003e\n                      \u003cth\u003eEvidencia\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003e1. Windows Defender: \u0026iquest;activo, actualizado, con an\u0026aacute;lisis programado?\u003c/td\u003e\u003ctd\u003eWindows Security \u0026rarr; Protecci\u0026oacute;n contra virus y amenazas\u003c/td\u003e\u003ctd\u003eCaptura del estado de protecci\u0026oacute;n\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e2. Firewall: estado en los 3 perfiles (Dominio, Privado, P\u0026uacute;blico)\u003c/td\u003e\u003ctd\u003ePanel de control \u0026rarr; Firewall de Windows\u003c/td\u003e\u003ctd\u003eCaptura de los 3 perfiles\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e3. Actualizaciones: \u0026iquest;al d\u0026iacute;a? \u0026iquest;cu\u0026aacute;ntas pendientes?\u003c/td\u003e\u003ctd\u003eConfiguraci\u0026oacute;n \u0026rarr; Windows Update \u0026rarr; Ver historial\u003c/td\u003e\u003ctd\u003eCaptura del historial\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e4. Cuentas de usuario: \u0026iquest;admin con contrase\u0026ntilde;a? \u0026iquest;cuentas innecesarias?\u003c/td\u003e\u003ctd\u003e\u003ckbd\u003eWin + R\u003c/kbd\u003e \u0026rarr; \u003ccode\u003elusrmgr.msc\u003c/code\u003e \u0026rarr; Usuarios\u003c/td\u003e\u003ctd\u003eCaptura de la lista de cuentas\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e5. Software instalado: \u0026iquest;sin licencia, desactualizado o desconocido?\u003c/td\u003e\u003ctd\u003eBelarc Advisor (belarc.com) \u0026mdash; reporte HTML\u003c/td\u003e\u003ctd\u003eReporte HTML + captura del resumen\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003e6. Copias de seguridad: \u0026iquest;existe estrategia activa?\u003c/td\u003e\u003ctd\u003eConfiguraci\u0026oacute;n \u0026rarr; Copia de seguridad\u003c/td\u003e\u003ctd\u003eCaptura del estado actual\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones (sin saltarte pasos)\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eAbre la Tabla de Diagn\u0026oacute;stico suministrada por el instructor. Encabezado: nombre completo, ficha, equipo asignado, fecha.\u003c/li\u003e\n                  \u003cli\u003eDescarga e instala Belarc Advisor (belarc.com). Ejec\u0026uacute;talo y guarda el reporte HTML.\u003c/li\u003e\n                  \u003cli\u003ePara cada uno de los 6 aspectos, sigue la ruta indicada, revisa el estado y registra los datos exactos.\u003c/li\u003e\n                  \u003cli\u003eToma captura de cada aspecto. N\u0026oacute;mbralas en orden: \u003ccode\u003e01_Defender.png\u003c/code\u003e, \u003ccode\u003e02_Firewall.png\u003c/code\u003e, \u003ccode\u003e03_Actualizaciones.png\u003c/code\u003e, \u003ccode\u003e04_Cuentas.png\u003c/code\u003e, \u003ccode\u003e05_Belarc.png\u003c/code\u003e, \u003ccode\u003e06_Backup.png\u003c/code\u003e.\u003c/li\u003e\n                  \u003cli\u003ePara cada hallazgo, asigna nivel de riesgo: \u003cstrong\u003eALTO\u003c/strong\u003e (acci\u0026oacute;n inmediata), \u003cstrong\u003eMEDIO\u003c/strong\u003e (atenci\u0026oacute;n pr\u0026oacute;xima), \u003cstrong\u003eBAJO\u003c/strong\u003e (mejora opcional). Justifica en observaciones.\u003c/li\u003e\n                  \u003cli\u003eOrganiza el reporte de Belarc y las 6 capturas en una carpeta: \u003ccode\u003eDiagnostico_[TuNombre]_[Fecha]\u003c/code\u003e.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (2 horas, DESPU\u0026Eacute;S de la sesi\u0026oacute;n)\u003c/div\u003e\n                \u003cp\u003eEscribe en tu bit\u0026aacute;cora un p\u0026aacute;rrafo de conclusi\u0026oacute;n t\u0026eacute;cnica (m\u0026iacute;nimo 8 l\u0026iacute;neas): estado general, 3 hallazgos m\u0026aacute;s cr\u0026iacute;ticos y controles prioritarios. Esta conclusi\u0026oacute;n forma parte de la Tabla de Diagn\u0026oacute;stico.\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eResumen del diagn\u0026oacute;stico (registro del aprendiz)\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Estado general de seguridad del equipo diagnosticado\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g7_331_estado\" data-track placeholder=\"Resume si el equipo est\u0026aacute; bien protegido, parcialmente o vulnerable, con datos del diagn\u0026oacute;stico.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Los 3 hallazgos m\u0026aacute;s cr\u0026iacute;ticos (con nivel de riesgo)\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g7_331_hallazgos\" data-track placeholder=\"Ej.: Defender desactivado (ALTO), Firewall p\u0026uacute;blico apagado (ALTO), 18 actualizaciones pendientes (MEDIO).\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Controles que priorizar\u0026iacute;as y por qu\u0026eacute;\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"g7_331_prioridades\" data-track placeholder=\"Lista los controles que aplicar\u0026iacute;as primero y justifica seg\u0026uacute;n el impacto en la informaci\u0026oacute;n.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Conclusi\u0026oacute;n t\u0026eacute;cnica (m\u0026iacute;nimo 8 l\u0026iacute;neas)\u003c/span\u003e\n                  \u003ctextarea rows=\"8\" data-store=\"g7_331_conclusion\" data-track placeholder=\"P\u0026aacute;rrafo final con tu lectura t\u0026eacute;cnica del estado del equipo.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"diagnostico331DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarDiagnostico331\" class=\"btn-save-response\" onclick=\"actStd_save_diagnostico331()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_diagnostico331()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusDiagnostico331\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-diagnostico331\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.3.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eImplementaci\u0026oacute;n de controles de hardening\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n t\u0026eacute;cnica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e aplicar 7 controles de \u003cem\u003ehardening\u003c/em\u003e de Windows priorizando por nivel de riesgo del diagn\u0026oacute;stico. Evidencia de Desempe\u0026ntilde;o (IE-02 \u0026iacute;tems 7-13).\u003c/p\u003e\n\n              \u003carticle class=\"support-card\"\u003e\n                \u003ch3\u003eDatos de la actividad\u003c/h3\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003e\u0026#9201; Duraci\u0026oacute;n: 10 horas (8 directas + 2 independientes).\u003c/li\u003e\n                  \u003cli\u003e\u0026#127979; Ambiente: laboratorio \u0026mdash; mismo equipo del diagn\u0026oacute;stico.\u003c/li\u003e\n                  \u003cli\u003e\u0026#127919; Estrategia: simulaci\u0026oacute;n t\u0026eacute;cnica con documentaci\u0026oacute;n de cambios.\u003c/li\u003e\n                  \u003cli\u003e\u0026#128190; Herramientas TIC: Windows Security Center, \u003ccode\u003esecpol.msc\u003c/code\u003e, \u003ccode\u003elusrmgr.msc\u003c/code\u003e, EaseUS Todo Backup Free (easeustodo.com) o Historial de archivos Windows.\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/article\u003e\n\n              \u003cdiv style=\"background:#1b5e20;color:#fff;border-radius:8px 8px 0 0;padding:10px 16px;font-size:0.82rem;font-weight:700;letter-spacing:0.04em;display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:16px;margin-bottom:0\"\u003e\n                \u003cspan\u003e\u0026#128203; EVIDENCIA \u0026mdash; Tipo: Desempe\u0026ntilde;o\u003c/span\u003e\n                \u003cspan style=\"opacity:0.5\"\u003e|\u003c/span\u003e\n                \u003cspan\u003eInstrumento: Lista de Chequeo IE-02 (\u0026iacute;tems 7-13)\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:0;border-radius:0 0 8px 8px;overflow:hidden;border:1px solid #c8e6c9;border-top:none\"\u003e\n                \u003ctable class=\"data-table\" style=\"margin:0\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth style=\"width:2rem;text-align:center\"\u003eN.\u0026deg;\u003c/th\u003e\n                      \u003cth\u003eControl\u003c/th\u003e\n                      \u003cth\u003eRuta / Herramienta\u003c/th\u003e\n                      \u003cth\u003eEvidencia\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e1\u003c/td\u003e\u003ctd\u003eActivar Windows Defender con an\u0026aacute;lisis semanal programado\u003c/td\u003e\u003ctd\u003eWindows Security \u0026rarr; Protecci\u0026oacute;n contra virus \u0026rarr; Opciones de an\u0026aacute;lisis\u003c/td\u003e\u003ctd\u003eCaptura: Defender activo + programaci\u0026oacute;n\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e2\u003c/td\u003e\u003ctd\u003eHabilitar Firewall en los 3 perfiles\u003c/td\u003e\u003ctd\u003ePanel de control \u0026rarr; Firewall de Windows \u0026rarr; Activar/desactivar\u003c/td\u003e\u003ctd\u003eCaptura: 3 perfiles habilitados\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e3\u003c/td\u003e\u003ctd\u003ePol\u0026iacute;tica de contrase\u0026ntilde;as: m\u0026iacute;n 8 caracteres, complejidad, caducidad 90 d\u0026iacute;as\u003c/td\u003e\u003ctd\u003e\u003ckbd\u003eWin + R\u003c/kbd\u003e \u0026rarr; \u003ccode\u003esecpol.msc\u003c/code\u003e \u0026rarr; Directiva de contrase\u0026ntilde;as\u003c/td\u003e\u003ctd\u003eCaptura: directiva con 3 par\u0026aacute;metros\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e4\u003c/td\u003e\u003ctd\u003eAsegurar cuentas: contrase\u0026ntilde;a en admin y deshabilitar innecesarias\u003c/td\u003e\u003ctd\u003e\u003ckbd\u003eWin + R\u003c/kbd\u003e \u0026rarr; \u003ccode\u003elusrmgr.msc\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eCaptura: cuentas innecesarias deshabilitadas\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e5\u003c/td\u003e\u003ctd\u003eActivar SmartScreen para aplicaciones y descargas\u003c/td\u003e\u003ctd\u003eConfiguraci\u0026oacute;n \u0026rarr; Privacidad y seguridad \u0026rarr; Seguridad de Windows\u003c/td\u003e\u003ctd\u003eCaptura: SmartScreen activo\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e6\u003c/td\u003e\u003ctd\u003eConfigurar actualizaciones autom\u0026aacute;ticas\u003c/td\u003e\u003ctd\u003eConfiguraci\u0026oacute;n \u0026rarr; Windows Update \u0026rarr; Opciones avanzadas\u003c/td\u003e\u003ctd\u003eCaptura: actualizaci\u0026oacute;n autom\u0026aacute;tica activa\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003e7\u003c/td\u003e\u003ctd\u003eImplementar copia de seguridad (estrategia 3-2-1)\u003c/td\u003e\u003ctd\u003eEaseUS Todo Backup Free o Historial de archivos Windows\u003c/td\u003e\u003ctd\u003eCaptura: copia ejecutada + destino\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#128204; Si un control no aplica\u003c/div\u003e\n                \u003cp\u003eSi un control no puede aplicarse (ej.: \u003ccode\u003esecpol.msc\u003c/code\u003e no disponible en Windows Home), documenta el motivo t\u0026eacute;cnico y describe c\u0026oacute;mo se aplicar\u0026iacute;a en un equipo con Windows Pro. Eso tambi\u0026eacute;n demuestra competencia.\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:14px\"\u003e\n                \u003ch3\u003eInstrucciones\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eRevisa tu Tabla de Diagn\u0026oacute;stico (Act. 3.3.1). Empieza por los hallazgos \u003cstrong\u003eALTO\u003c/strong\u003e, luego \u003cstrong\u003eMEDIO\u003c/strong\u003e.\u003c/li\u003e\n                  \u003cli\u003ePara cada control: sigue la ruta, implementa el cambio y toma captura.\u003c/li\u003e\n                  \u003cli\u003eEn tu Bit\u0026aacute;cora de cambios registra: (a) estado antes, (b) acci\u0026oacute;n, (c) estado despu\u0026eacute;s, (d) observaciones.\u003c/li\u003e\n                  \u003cli\u003eSi aparece un error, copia el mensaje, busca soluci\u0026oacute;n en learn.microsoft.com y registra error + soluci\u0026oacute;n.\u003c/li\u003e\n                  \u003cli\u003eNombra cada captura: \u003ccode\u003e01_Defender_configurado.png\u003c/code\u003e, \u003ccode\u003e02_Firewall_3perfiles.png\u003c/code\u003e, \u003ccode\u003e03_Politica_contras.png\u003c/code\u003e, \u003ccode\u003e04_Cuentas_aseguradas.png\u003c/code\u003e, \u003ccode\u003e05_SmartScreen.png\u003c/code\u003e, \u003ccode\u003e06_Actualizaciones.png\u003c/code\u003e, \u003ccode\u003e07_Backup_exitoso.png\u003c/code\u003e. Carpeta: \u003ccode\u003eHardening_[TuNombre]_[Fecha]\u003c/code\u003e.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (2 horas, DESPU\u0026Eacute;S de la sesi\u0026oacute;n)\u003c/div\u003e\n                \u003cp\u003eCompleta la Bit\u0026aacute;cora con la conclusi\u0026oacute;n comparativa: \u0026iquest;cu\u0026aacute;nto mejor\u0026oacute; la postura de seguridad? Compara antes/despu\u0026eacute;s de los 7 controles. \u0026iquest;Cu\u0026aacute;les tuvieron mayor impacto? M\u0026iacute;nimo 10 l\u0026iacute;neas.\u003c/p\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eBit\u0026aacute;cora de cambios (registro del aprendiz)\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Orden en que aplicaste los 7 controles (seg\u0026uacute;n riesgo)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g7_332_orden\" data-track placeholder=\"Ej.: 1) Defender, 2) Firewall, 3) Backup, 4) Contrase\u0026ntilde;as, ...\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Resumen de cambios aplicados (estado antes / acci\u0026oacute;n / estado despu\u0026eacute;s)\u003c/span\u003e\n                  \u003ctextarea rows=\"8\" data-store=\"g7_332_resumen\" data-track placeholder=\"Para cada control, describe el cambio.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Errores encontrados y soluci\u0026oacute;n aplicada (si aplica)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g7_332_errores\" data-track placeholder=\"Mensaje exacto + fuente consultada + soluci\u0026oacute;n.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Conclusi\u0026oacute;n comparativa (m\u0026iacute;nimo 10 l\u0026iacute;neas)\u003c/span\u003e\n                  \u003ctextarea rows=\"10\" data-store=\"g7_332_conclusion\" data-track placeholder=\"\u0026iquest;Cu\u0026aacute;nto mejor\u0026oacute; la postura de seguridad? \u0026iquest;Qu\u0026eacute; controles tuvieron mayor impacto?\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"hardening332DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarHardening332\" class=\"btn-save-response\" onclick=\"actStd_save_hardening332()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_hardening332()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusHardening332\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-hardening332\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.4 TRANSFERENCIA ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"transferencia\" class=\"section-title\"\u003e3.4 \u0026middot; Actividades de Transferencia del Conocimiento\u003c/div\u003e\n      \u003cdiv class=\"info-box blue\" style=\"margin-bottom:16px\"\u003e\n        \u003cp\u003eIntegrar todo lo aprendido en un producto t\u0026eacute;cnico real para una MiPyme de Boyac\u0026aacute;.\n        La mayor parte de la redacci\u0026oacute;n del plan es trabajo independiente; la clase se usa para\n        orientar la estructura y para la sustentaci\u0026oacute;n.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-transferencia\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128640;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Transferencia\u003c/h3\u003e\n              \u003cp\u003e1 actividad \u0026middot; Duraci\u0026oacute;n: 6 horas (2 directas + 4 independientes)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003c!-- ───────── Actividad 3.4.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.4.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003ePlan de Ciberseguridad para una MiPyme + Sustentaci\u0026oacute;n oral\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisi\u0026oacute;n integradora\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e consolidar diagn\u0026oacute;stico, controles, inventario y recomendaciones en un Plan formal para ElectroBoyc\u0026aacute; S.A.S. y sustentarlo oralmente. Producto + Sustentaci\u0026oacute;n (IE-03).\u003c/p\u003e\n\n              \u003carticle class=\"support-card\"\u003e\n                \u003ch3\u003eDatos de la actividad\u003c/h3\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003e\u0026#9201; Duraci\u0026oacute;n: 6 horas (2 directas: orientaci\u0026oacute;n + sustentaci\u0026oacute;n; 4 independientes: redacci\u0026oacute;n).\u003c/li\u003e\n                  \u003cli\u003e\u0026#127979; Ambiente: laboratorio con internet y videobeam.\u003c/li\u003e\n                  \u003cli\u003e\u0026#127919; Estrategia: aprendizaje basado en producto + heteroevaluaci\u0026oacute;n oral.\u003c/li\u003e\n                  \u003cli\u003e\u0026#128190; Herramientas TIC: LibreOffice Writer / Word, Calc / Sheets, Canva (canva.com) o Google Slides, PDF24 (pdf24.org).\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"story-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003e\u0026#127970; Escenario \u0026mdash; ElectroBoyc\u0026aacute; S.A.S., Puerto Boyac\u0026aacute;\u003c/h3\u003e\n                \u003cp\u003eEl mismo caso de la reflexi\u0026oacute;n inicial. Tras el ciberataque, la empresa te contrata como\n                t\u0026eacute;cnico de sistemas para evaluar su situaci\u0026oacute;n y elaborar un plan que evite futuros\n                incidentes. Tienes los resultados del diagn\u0026oacute;stico (Act. 3.3.1) y los controles\n                implementados (Act. 3.3.2). Ahora consol\u0026iacute;dalos en un Plan formal y pres\u0026eacute;ntalo a la\n                gerencia.\u003c/p\u003e\n              \u003c/article\u003e\n\n              \u003cdiv style=\"background:#1b5e20;color:#fff;border-radius:8px 8px 0 0;padding:10px 16px;font-size:0.82rem;font-weight:700;letter-spacing:0.04em;display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:16px;margin-bottom:0\"\u003e\n                \u003cspan\u003e\u0026#128203; EVIDENCIA \u0026mdash; Tipo: Producto + Sustentaci\u0026oacute;n Oral\u003c/span\u003e\n                \u003cspan style=\"opacity:0.5\"\u003e|\u003c/span\u003e\n                \u003cspan\u003eInstrumento: Lista de Chequeo IE-03\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll\" style=\"margin-top:0;border-radius:0 0 8px 8px;overflow:hidden;border:1px solid #c8e6c9;border-top:none\"\u003e\n                \u003ctable class=\"data-table\" style=\"margin:0\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth style=\"width:2rem;text-align:center\"\u003eSec.\u003c/th\u003e\n                      \u003cth\u003eSecci\u0026oacute;n del plan\u003c/th\u003e\n                      \u003cth\u003eContenido m\u0026iacute;nimo requerido\u003c/th\u003e\n                      \u003cth\u003eExtensi\u0026oacute;n\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003eA\u003c/td\u003e\u003ctd\u003eResumen ejecutivo\u003c/td\u003e\u003ctd\u003eSituaci\u0026oacute;n actual, riesgos del diagn\u0026oacute;stico y objetivos del plan.\u003c/td\u003e\u003ctd\u003e1 p\u0026aacute;gina\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003eB\u003c/td\u003e\u003ctd\u003eDiagn\u0026oacute;stico de seguridad\u003c/td\u003e\u003ctd\u003eTabla resumen de hallazgos con niveles de riesgo (Act. 3.3.1).\u003c/td\u003e\u003ctd\u003e1-2 p\u0026aacute;ginas\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003eC\u003c/td\u003e\u003ctd\u003eControles implementados\u003c/td\u003e\u003ctd\u003eTabla de los 7 controles (Act. 3.3.2) con estado (Implementado / Parcial / No aplica).\u003c/td\u003e\u003ctd\u003e1 p\u0026aacute;gina\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003eD\u003c/td\u003e\u003ctd\u003eInventario de activos con valoraci\u0026oacute;n de riesgos\u003c/td\u003e\u003ctd\u003eID, nombre, tipo, propietario, criticidad, amenaza, control aplicado.\u003c/td\u003e\u003ctd\u003e1-2 p\u0026aacute;ginas\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003eE\u003c/td\u003e\u003ctd\u003eEstrategia de copias de seguridad\u003c/td\u003e\u003ctd\u003eTipo de backup, frecuencia, herramienta, almacenamiento, esquema 3-2-1.\u003c/td\u003e\u003ctd\u003e1 p\u0026aacute;gina\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003eF\u003c/td\u003e\u003ctd\u003eRecomendaciones a mediano plazo\u003c/td\u003e\u003ctd\u003eM\u0026iacute;nimo 3 mejoras con referencia a ISO 27001, NIST CSF o Ley 1273.\u003c/td\u003e\u003ctd\u003e1 p\u0026aacute;gina\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd style=\"text-align:center;font-weight:700\"\u003eG\u003c/td\u003e\u003ctd\u003eBibliograf\u0026iacute;a\u003c/td\u003e\u003ctd\u003eM\u0026iacute;nimo 5 fuentes: normas, gu\u0026iacute;as, documentaci\u0026oacute;n oficial. APA o IEEE.\u003c/td\u003e\u003ctd\u003e1 p\u0026aacute;gina\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eDistribuci\u0026oacute;n de las 6 horas\u003c/h3\u003e\n                \u003cul class=\"note-list\"\u003e\n                  \u003cli\u003e\u003cstrong\u003e1 hora directa (Sesi\u0026oacute;n 1):\u003c/strong\u003e el instructor orienta la estructura del plan, revisa el borrador del \u0026iacute;ndice y resuelve dudas.\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003e4 horas independientes:\u003c/strong\u003e redacci\u0026oacute;n completa del plan (secciones A-G).\u003c/li\u003e\n                  \u003cli\u003e\u003cstrong\u003e1 hora directa (Sesi\u0026oacute;n 2):\u003c/strong\u003e sustentaci\u0026oacute;n oral de 10 minutos por aprendiz o equipo + preguntas del instructor (5 min).\u003c/li\u003e\n                \u003c/ul\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones \u0026mdash; Sesi\u0026oacute;n directa 1 (orientaci\u0026oacute;n)\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eLee el escenario de ElectroBoyc\u0026aacute; y los resultados de tus actividades 3.3.1 y 3.3.2.\u003c/li\u003e\n                  \u003cli\u003eEscribe el \u0026iacute;ndice del plan con los t\u0026iacute;tulos A-G y una frase por secci\u0026oacute;n. El instructor revisa antes de terminar la clase.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones \u0026mdash; Trabajo independiente (redacci\u0026oacute;n)\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003eRedacta el plan en LibreOffice Writer o Word usando el \u0026iacute;ndice aprobado. Incorpora capturas y tablas de 3.3.1 y 3.3.2 como evidencias.\u003c/li\u003e\n                  \u003cli\u003ePara el inventario (secci\u0026oacute;n D), crea la tabla en Calc o Sheets con las columnas indicadas. Expor\u0026aacute;la a PDF e incorp\u0026oacute;rala al plan.\u003c/li\u003e\n                  \u003cli\u003eVerifica: m\u0026iacute;nimo 8 p\u0026aacute;ginas, todas las secciones A-G, libre de errores de ortograf\u0026iacute;a.\u003c/li\u003e\n                  \u003cli\u003eExporta a PDF: \u003ccode\u003eArchivo \u0026gt; Exportar como PDF\u003c/code\u003e o PDF24 (pdf24.org). Nombre: \u003cstrong\u003ePlanCiberseguridad_[TuNombre].pdf\u003c/strong\u003e.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"support-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003eInstrucciones \u0026mdash; Sesi\u0026oacute;n directa 2 (sustentaci\u0026oacute;n)\u003c/h3\u003e\n                \u003col style=\"padding-left:1.4rem;margin:0;line-height:1.7\"\u003e\n                  \u003cli\u003ePrepara una presentaci\u0026oacute;n de m\u0026aacute;ximo 8 diapositivas en Canva o Google Slides: (1) Portada, (2-3) Diagn\u0026oacute;stico, (4-5) Controles, (6) Inventario, (7) Recomendaciones, (8) Lecciones aprendidas.\u003c/li\u003e\n                  \u003cli\u003ePresenta tu plan al instructor en 10 minutos. El instructor har\u0026aacute; preguntas t\u0026eacute;cnicas durante 5 minutos.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n\n              \u003carticle class=\"notes-card\" style=\"margin-top:16px\"\u003e\n                \u003ch3\u003e\u0026Iacute;ndice del Plan de Ciberseguridad (borrador previo a la redacci\u0026oacute;n)\u003c/h3\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eA. Resumen ejecutivo (qu\u0026eacute; incluir\u0026aacute;s en una frase)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g7_341_sec_a\" data-track placeholder=\"Situaci\u0026oacute;n actual, riesgos identificados, objetivos del plan.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eB. Diagn\u0026oacute;stico de seguridad (qu\u0026eacute; incluir\u0026aacute;s)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g7_341_sec_b\" data-track placeholder=\"Tabla resumen de hallazgos de la Act. 3.3.1.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eC. Controles implementados (qu\u0026eacute; incluir\u0026aacute;s)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g7_341_sec_c\" data-track placeholder=\"Tabla de los 7 controles de hardening de la Act. 3.3.2.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eD. Inventario de activos (qu\u0026eacute; incluir\u0026aacute;s)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g7_341_sec_d\" data-track placeholder=\"ID, nombre, tipo, propietario, criticidad, amenaza, control.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eE. Estrategia de copias de seguridad (qu\u0026eacute; incluir\u0026aacute;s)\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"g7_341_sec_e\" data-track placeholder=\"Backup elegido, frecuencia, herramienta, almacenamiento, 3-2-1.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eF. Recomendaciones a mediano plazo (m\u0026iacute;nimo 3 con norma)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"g7_341_sec_f\" data-track placeholder=\"3 mejoras adicionales referenciando ISO 27001, NIST CSF o Ley 1273.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003eG. Bibliograf\u0026iacute;a (5 fuentes m\u0026iacute;nimo, APA o IEEE)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"g7_341_sec_g\" data-track placeholder=\"Lista tus 5 fuentes con formato APA o IEEE.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv id=\"plan341DeadlineControls\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarPlan341\" class=\"btn-save-response\" onclick=\"actStd_save_plan341()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_plan341()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusPlan341\" class=\"activity-saved-notice\" style=\"display:none;margin-top:10px;padding:10px 14px;background:#e8f5e9;border-left:4px solid #2e7d32;border-radius:6px;color:#1b5e20;font-size:0.88rem\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv id=\"driveDeliveryPanel-plan341\" style=\"margin-top:16px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ EVIDENCIAS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"evidencias\" class=\"section-title\"\u003ePlanteamiento de Evidencias para la Evaluaci\u0026oacute;n\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e3f2fd\"\u003e\u0026#128202;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eTabla de Evidencias del Proceso Formativo\u003c/h3\u003e\n              \u003cp\u003e3 evidencias: conocimiento, desempe\u0026ntilde;o y producto\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\n                \u003ctr\u003e\n                  \u003cth\u003eActividad de Aprendizaje\u003c/th\u003e\n                  \u003cth\u003eEvidencias\u003c/th\u003e\n                  \u003cth\u003eCriterios\u003c/th\u003e\n                  \u003cth\u003eInstrumento\u003c/th\u003e\n                \u003c/tr\u003e\n              \u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.2.2 \u0026mdash; Mapa conceptual de ciberseguridad RAP 03\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003eCONOCIMIENTO:\u003c/strong\u003e mapa conceptual en PDF (m\u0026iacute;n. 15 conceptos), relaci\u0026oacute;n ataques \u0026rarr; controles \u0026rarr; inventario \u0026rarr; plan, Triada CIA, normativa, 2 controles de \u003cem\u003ehardening\u003c/em\u003e. Presentaci\u0026oacute;n oral de 5 min.\u003c/td\u003e\n                  \u003ctd\u003ePlanifica la seguridad identificando amenazas, vulnerabilidades, riesgos y controles. Relaciona ataques, controles, inventario y normativa (ISO/IEC 27001, NIST CSF, Ley 1273) en MiPyme. Sustenta con claridad t\u0026eacute;cnica.\u003c/td\u003e\n                  \u003ctd\u003eLista de Chequeo IE-01\u003c/td\u003e\n                \u003c/tr\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.3.1 + 3.3.2 \u0026mdash; Diagn\u0026oacute;stico y hardening del equipo\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003eDESEMPE\u0026Ntilde;O:\u003c/strong\u003e Tabla de Diagn\u0026oacute;stico con niveles de riesgo; carpeta \u003ccode\u003eDiagnostico_[TuNombre]_[Fecha]\u003c/code\u003e con 6 capturas + reporte Belarc; Bit\u0026aacute;cora de cambios; carpeta \u003ccode\u003eHardening_[TuNombre]_[Fecha]\u003c/code\u003e con 7 capturas; conclusiones t\u0026eacute;cnica y comparativa.\u003c/td\u003e\n                  \u003ctd\u003eDiagnostica el estado de protecci\u0026oacute;n con herramientas t\u0026eacute;cnicas. Clasifica riesgos y justifica hallazgos. Aplica controles de \u003cem\u003ehardening\u003c/em\u003e seg\u0026uacute;n diagn\u0026oacute;stico, normativa y restricciones. Documenta antes/acci\u0026oacute;n/despu\u0026eacute;s con evidencias verificables.\u003c/td\u003e\n                  \u003ctd\u003eLista de Chequeo IE-02\u003c/td\u003e\n                \u003c/tr\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.4.1 \u0026mdash; Plan de Ciberseguridad + Sustentaci\u0026oacute;n oral\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003ePRODUCTO:\u003c/strong\u003e \u0026Iacute;ndice aprobado; Plan en PDF (m\u0026iacute;n. 8 p\u0026aacute;ginas, secciones A-G); presentaci\u0026oacute;n de m\u0026aacute;x. 8 diapositivas; sustentaci\u0026oacute;n oral de 10 min + preguntas t\u0026eacute;cnicas del instructor.\u003c/td\u003e\n                  \u003ctd\u003eElabora un plan de ciberseguridad para una MiPyme integrando diagn\u0026oacute;stico, controles, inventario con valoraci\u0026oacute;n y estrategia 3-2-1. Formula recomendaciones viables con soporte t\u0026eacute;cnico y normativo. Sustenta con dominio t\u0026eacute;cnico.\u003c/td\u003e\n                  \u003ctd\u003eLista de Chequeo IE-03\u003c/td\u003e\n                \u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ GLOSARIO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"glosario\" class=\"section-title\"\u003eGlosario de T\u0026eacute;rminos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#fff3e0\"\u003e\u0026#128214;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eConceptos clave de ciberseguridad\u003c/h3\u003e\n              \u003cp\u003e19 t\u0026eacute;rminos t\u0026eacute;cnicos y normativos\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdl class=\"glossary-list\"\u003e\n            \u003cdt\u003eActivo de informaci\u0026oacute;n\u003c/dt\u003e\u003cdd\u003eCualquier dato, documento o recurso informacional (digital o f\u0026iacute;sico) que tiene valor para la organizaci\u0026oacute;n y debe protegerse.\u003c/dd\u003e\n            \u003cdt\u003eAmenaza\u003c/dt\u003e\u003cdd\u003eCausa potencial de un incidente no deseado que puede resultar en da\u0026ntilde;o a un sistema o activo de informaci\u0026oacute;n.\u003c/dd\u003e\n            \u003cdt\u003eAn\u0026aacute;lisis de riesgos\u003c/dt\u003e\u003cdd\u003eProceso para identificar amenazas y vulnerabilidades, estimar su probabilidad/impacto y priorizar controles de mitigaci\u0026oacute;n.\u003c/dd\u003e\n            \u003cdt\u003eBackup (copia de seguridad)\u003c/dt\u003e\u003cdd\u003eCopia de datos o sistemas para recuperaci\u0026oacute;n ante p\u0026eacute;rdida, corrupci\u0026oacute;n o incidente; se recomienda automatizar y verificar.\u003c/dd\u003e\n            \u003cdt\u003eBitLocker\u003c/dt\u003e\u003cdd\u003eFuncionalidad de Windows para cifrado de unidad que protege datos frente a acceso no autorizado en caso de p\u0026eacute;rdida o robo.\u003c/dd\u003e\n            \u003cdt\u003eCiberseguridad\u003c/dt\u003e\u003cdd\u003eConjunto de pr\u0026aacute;cticas, procesos y controles orientados a proteger sistemas, redes y datos frente a amenazas digitales.\u003c/dd\u003e\n            \u003cdt\u003eTriada CIA\u003c/dt\u003e\u003cdd\u003ePrincipios de seguridad de la informaci\u0026oacute;n: \u003cstrong\u003eConfidencialidad, Integridad y Disponibilidad\u003c/strong\u003e.\u003c/dd\u003e\n            \u003cdt\u003eControl de seguridad\u003c/dt\u003e\u003cdd\u003eMedida preventiva, detectiva o correctiva que reduce la probabilidad o el impacto de un riesgo.\u003c/dd\u003e\n            \u003cdt\u003eFirewall\u003c/dt\u003e\u003cdd\u003eComponente que filtra el tr\u0026aacute;fico de red seg\u0026uacute;n reglas definidas, permitiendo o bloqueando conexiones.\u003c/dd\u003e\n            \u003cdt\u003eHardening\u003c/dt\u003e\u003cdd\u003eProceso de configuraci\u0026oacute;n segura de un sistema operativo para reducir vulnerabilidades.\u003c/dd\u003e\n            \u003cdt\u003eIncidente de seguridad\u003c/dt\u003e\u003cdd\u003eEvento que compromete o puede comprometer la confidencialidad, integridad o disponibilidad de la informaci\u0026oacute;n.\u003c/dd\u003e\n            \u003cdt\u003eIngenier\u0026iacute;a social\u003c/dt\u003e\u003cdd\u003eT\u0026eacute;cnicas de manipulaci\u0026oacute;n para inducir a una persona a revelar informaci\u0026oacute;n sensible o ejecutar acciones que comprometen la seguridad.\u003c/dd\u003e\n            \u003cdt\u003eMalware\u003c/dt\u003e\u003cdd\u003eSoftware malicioso dise\u0026ntilde;ado para da\u0026ntilde;ar, alterar, cifrar, espiar o tomar control de sistemas y datos.\u003c/dd\u003e\n            \u003cdt\u003ePhishing\u003c/dt\u003e\u003cdd\u003eAtaque que utiliza correos, mensajes o sitios falsos para enga\u0026ntilde;ar al usuario y obtener credenciales o informaci\u0026oacute;n sensible.\u003c/dd\u003e\n            \u003cdt\u003ePol\u0026iacute;tica de seguridad\u003c/dt\u003e\u003cdd\u003eDocumento que establece reglas, responsabilidades y controles para proteger la informaci\u0026oacute;n de una organizaci\u0026oacute;n.\u003c/dd\u003e\n            \u003cdt\u003eRansomware\u003c/dt\u003e\u003cdd\u003eTipo de malware que cifra archivos o sistemas y exige un pago para recuperar el acceso a la informaci\u0026oacute;n.\u003c/dd\u003e\n            \u003cdt\u003eSGSI\u003c/dt\u003e\u003cdd\u003eSistema de Gesti\u0026oacute;n de Seguridad de la Informaci\u0026oacute;n; modelo basado en ISO 27001 para establecer, implementar y mejorar la seguridad.\u003c/dd\u003e\n            \u003cdt\u003eSmartScreen\u003c/dt\u003e\u003cdd\u003eFunci\u0026oacute;n de seguridad de Windows que advierte sobre aplicaciones, archivos o sitios potencialmente maliciosos antes de su ejecuci\u0026oacute;n.\u003c/dd\u003e\n            \u003cdt\u003eVulnerabilidad\u003c/dt\u003e\u003cdd\u003eDebilidad en un sistema, proceso, configuraci\u0026oacute;n o persona que puede ser explotada por una amenaza.\u003c/dd\u003e\n          \u003c/dl\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ REFERENCIAS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"referencias\" class=\"section-title\"\u003eReferentes Bibliogr\u0026aacute;ficos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#ede7f6\"\u003e\u0026#128279;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eFuentes oficiales y normativas\u003c/h3\u003e\n              \u003cp\u003e11 referencias t\u0026eacute;cnicas y normativas para consulta\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003col class=\"references-list\" style=\"padding-left:1.4rem;line-height:1.8\"\u003e\n            \u003cli\u003eISO. (2022). \u003cem\u003eISO/IEC 27001:2022 \u0026mdash; Information security management systems\u003c/em\u003e. \u003ca href=\"https://www.iso.org/standard/27001\" target=\"_blank\" rel=\"noopener\"\u003eiso.org/standard/27001\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eNIST. (2024). \u003cem\u003eMarco de Ciberseguridad (CSF) 2.0\u003c/em\u003e. NIST CSWP 29. \u003ca href=\"https://nvlpubs.nist.gov/nistpubs/CSWP/NIST.CSWP.29.spa.pdf\" target=\"_blank\" rel=\"noopener\"\u003envlpubs.nist.gov\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eDNP. (2020). \u003cem\u003eCONPES 3995: Pol\u0026iacute;tica Nacional de Confianza y Seguridad Digital\u003c/em\u003e. \u003ca href=\"https://colaboracion.dnp.gov.co/cdt/Conpes/Econ%C3%B3micos/3995.pdf\" target=\"_blank\" rel=\"noopener\"\u003ecolaboracion.dnp.gov.co\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eCongreso de Colombia. (2009). \u003cem\u003eLey 1273 de 2009 \u0026mdash; Delitos inform\u0026aacute;ticos\u003c/em\u003e. Diario Oficial No. 47.223. \u003ca href=\"https://www.secretariasenado.gov.co/senado/basedoc/ley_1273_2009.html\" target=\"_blank\" rel=\"noopener\"\u003esecretariasenado.gov.co\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMinTIC. (2021). \u003cem\u003eEstrategia Nacional de Seguridad Digital de Colombia\u003c/em\u003e. \u003ca href=\"https://www.mintic.gov.co\" target=\"_blank\" rel=\"noopener\"\u003emintic.gov.co\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMinTIC. (2016). \u003cem\u003eGu\u0026iacute;a para la Gesti\u0026oacute;n y Clasificaci\u0026oacute;n de Activos de Informaci\u0026oacute;n\u003c/em\u003e. \u003ca href=\"https://gobiernodigital.mintic.gov.co/692/articles-5482_G5_Gestion_Clasificacion.pdf\" target=\"_blank\" rel=\"noopener\"\u003egobiernodigital.mintic.gov.co\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMicrosoft. (2025). \u003cem\u003eProgramar an\u0026aacute;lisis con Microsoft Defender\u003c/em\u003e. \u003ca href=\"https://learn.microsoft.com/en-us/defender-endpoint/schedule-antivirus-scans\" target=\"_blank\" rel=\"noopener\"\u003elearn.microsoft.com\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eVeeam. (2025). \u003cem\u003eVeeam Agent for Microsoft Windows \u0026mdash; Backup\u003c/em\u003e. \u003ca href=\"https://helpcenter.veeam.com/docs/agentforwindows/userguide/backup.html\" target=\"_blank\" rel=\"noopener\"\u003ehelpcenter.veeam.com\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eINCIBE. \u003cem\u003ePol\u0026iacute;ticas de seguridad para la pyme\u003c/em\u003e. \u003ca href=\"https://www.incibe.es/empresas/herramientas/politicas\" target=\"_blank\" rel=\"noopener\"\u003eincibe.es/empresas/herramientas/politicas\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eCisco Skills for All. \u003cem\u003eIntroducci\u0026oacute;n a Ciberseguridad\u003c/em\u003e. \u003ca href=\"https://skillsforall.com/course/introduction-to-cybersecurity\" target=\"_blank\" rel=\"noopener\"\u003eskillsforall.com\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eBelarc. \u003cem\u003eBelarc Advisor \u0026mdash; Inventario de sistema\u003c/em\u003e. \u003ca href=\"https://www.belarc.com/products/belarc-advisor\" target=\"_blank\" rel=\"noopener\"\u003ebelarc.com/products/belarc-advisor\u003c/a\u003e\u003c/li\u003e\n          \u003c/ol\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n    \u003c/div\u003e\n  \u003c/div\u003e\n\u003c/div\u003e\n";
